def get_total_number_of_sequences(m, n):
    # Memoization table to store the results of subproblems
    memo = {}

    def count_sequences(value, length):
        if (value, length) in memo:
            return memo[(value, length)]

        if length == 1:
            return 1

        count = 0
        for prev_value in range(1, value // 2 + 1):
            count += count_sequences(prev_value, length - 1)

        memo[(value, length)] = count
        return count

    # Sum up all sequences of length n
    total_count = 0
    for start_value in range(1, m + 1):
        total_count += count_sequences(start_value, n)

    return total_count

